    cerrarRecursos();
}

bad_example:
list.forEach(item -> {
    try {
        procesar(item); // lanza IOException checked
    } catch (Exception e) {
        // tragado, sin logging ni re-throw
    }
});

good_example:
list.forEach(item -> {
    try {
        procesar(item);
    } catch (IOException e) {
        throw new RuntimeException("fallo procesando " + item, e);
    }
});
